.qsm-hint-wrapper {
	display: block;
	margin: 14px 0 6px;
	clear: both;
}

.qsm-hint-wrapper .qsm-hint-toggle {
	display: inline-flex;
	align-items: center;
	gap: 8px;
	padding: 8px 4px;
	min-height: 36px;
	background: transparent;
	border: 0;
	color: var(--qsm-hint-accent);
	font-family: inherit;
	font-size: 15px;
	font-weight: 500;
	line-height: 1.2;
