  width: 20px;
  position: absolute;
  right: 0;
  top: 12px;
  -webkit-border-radius: 20px;
  -moz-border-radius: 20px;
  border-radius: 20px;

}

.qsm-quiz-form .qmn_error .qmn_radio_answers,
.qsm-quiz-form .qmn_error .qmn_check_answers,
.qsm-quiz-form .qmn_error .qmn_accept_answers{
  border: 1px solid #da4f49;
  background: #F2DEDE;
  padding: 5px;
  -webkit-border-radius: 3px;
  -moz-border-radius: 3px;
  border-radius: 3px;
}

.qmn_btn:hover,
.qmn_quiz_container .btn:hover {
  color: #fff;
  background: #666;
}

.qmn_pagination, .qsm_auto_pagination_enabled .qmn_pagination {
  position: relative;
  display: flex;
  align-items: start;
  flex-direction: row-reverse;
  padding: 15px 0 15px 0;
  flex-wrap: wrap;
  justify-content: center;
  width: 100% !important;
  margin: 3px;
}

.qmn_pagination .mlw_previous {
  margin-right: 5px;
  margin-top: 5px;
}

.qmn_pagination .mlw_next, .qmn_pagination .qsm-submit-btn {
  margin-top: 5px;
}

.qmn_pagination :nth-child(0) { order: 0; }
.qmn_pagination :nth-child(1) { order: 1; }
.qmn_pagination :nth-child(2) { order: 2; }

.qsm_auto_pagination_enabled .qmn_pagination  :nth-child(5) { order: 0; }
.qsm_auto_pagination_enabled .qmn_pagination  :nth-child(6) { order: 1; }
.qsm_auto_pagination_enabled .qmn_pagination  :nth-child(7) { order: 2; }

@media screen and (min-width: 500px) {
  .qmn_pagination, .qsm_auto_pagination_enabled .qmn_pagination {
    justify-content: space-between;
    align-items: center;
    flex-direction: row;
    flex-wrap: initial;
  }
  .qmn_pagination :nth-child(0) { order: initial; }
  .qmn_pagination :nth-child(1) { order: initial; }
  .qmn_pagination :nth-child(2) { order: initial; }
  .qsm_auto_pagination_enabled .qmn_pagination  :nth-child(5) { order: initial; }
  .qsm_auto_pagination_enabled .qmn_pagination  :nth-child(6) { order: initial; }
  .qsm_auto_pagination_enabled .qmn_pagination  :nth-child(7) { order: initial; }
}

.mlw_qmn_timer {
  z-index: 999;
  display: inline-block;
  position: fixed;
  bottom: 20px;
  right: 20px;
  height: 50px;
  line-height: 50px;
  padding: 0 20px;
  background: #34495e;
  color: #fff;
  -webkit-border-radius: 50px;
  -moz-border-radius: 50px;
  border-radius: 50px;
  -webkit-box-shadow: 0 4px 8px rgba(0, 0, 0, .10);
  -moz-box-shadow: 0 4px 8px rgba(0, 0, 0, .10);
  box-shadow: 0 4px 8px rgba(0, 0, 0, .10);
}

.qmn_quiz_container select,
.qmn_quiz_container textarea,
.qmn_quiz_container input[type="text"],
.qmn_quiz_container input[type="email"],
.qmn_quiz_container input[type="url"],
.qmn_quiz_container input[type="number"],
.qmn_quiz_container input[type="date"] {
  background: #fff;
  border: 1px solid #3498db;
}

.qmn_quiz_container select:hover,
.qmn_quiz_container textarea:hover,
.qmn_quiz_container input[type="text"]:hover,
.qmn_quiz_container input[type="email"]:hover,
.qmn_quiz_container input[type="url"]:hover,
.qmn_quiz_container input[type="number"]:hover,
.qmn_quiz_container select:focus,
.qmn_quiz_container textarea:focus,
.qmn_quiz_container input[type="text"]:focus,
.qmn_quiz_container input[type="email"]:focus,
.qmn_quiz_container input[type="url"]:focus,
.qmn_quiz_container input[type="number"]:focus,
.qmn_quiz_container input[type="date"]:focus {
  outline: 0;
  background: #fff;
  border: 1px solid #3498db;
  -webkit-box-shadow: 0 0 10px rgba(52, 152, 219, .35);
  -moz-box-shadow: 0 0 10px rgba(52, 152, 219, .35);
  box-shadow: 0 0 10px rgba(52, 152, 219, .35);
}

.qmn_quiz_container .qmn_btn,
.qmn_quiz_container .btn {
  color: #fff !important;
  background: #3498db !important;
}

.qmn_quiz_container .qmn_btn:hover,
.qmn_quiz_container .btn:hover {
  background: #2980b9 !important;
}

/* Helper classes */

.border-none {
  border: 0;
}

.margin-bottom {
  margin-bottom: 20px;
}


@media (max-width: 768px) {

  .quiz_section label,
  .quiz_section .mlw_qmn_question {
    font-size: 18px;
  }

  .quiz_section p.form-help {
    font-size: 14px;
  }

  .quiz_section select,
  .quiz_section textarea,
  .quiz_section input[type="text"] {
    display: block;
    width: 100%;
    padding: 12px 10px 12px 10px;
    font-size: 16px;
  }

  .mlw_previous,
  .mlw_next,
  .qmn_page_counter_message {
    display: inline-block;
    text-align: center;
    position: relative;
    top: 0;
    left: 0;
    right: 0;
  }

}

.quick-question-res-p {
  border: 2px solid;
  padding: 5px 10px;
  margin: 0;
  border-radius: 5px;
}

.mlw_qmn_quiz_link {
  cursor: pointer;
}

.qsm-results-page .qmn_question_answer {
  margin-bottom: 30px;
}

.page-timer-wrapper {
  display: flex;
  max-width: 100%;
  box-sizing: border-box;
  text-align: center;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.page-timer-wrapper .qsm-pagetimer {
  font-size: 18px;
  font-weight: bold;
  line-height: 24px;
  color: #333;
  padding: 5px 10px;
  box-shadow: 0 0 10px 1px #eee;
  border-radius: 5px;
}

.page-timer-wrapper .qsm-pagetimer-warning {
  box-sizing: border-box;
  color: red;
  font-size: 18px;
  line-height: 24px;
}

.data-correct-answer {
    color: green;
}

